def parse_implicit_response(uri, state=None, scope=None):
    if not is_secure_transport(uri):
        raise InsecureTransportError()

    fragment = urlparse.urlparse(uri).fragment
    params = dict(urlparse.parse_qsl(fragment, keep_blank_values=True))

    if 'scope' in params:
        params['scope'] = scope_to_list(params['scope'])

    if 'expires_in' in params:
        if params['expires_in'] is None:
            params.pop('expires_in')
        else:
            params['expires_at'] = time.time() + int(params['expires_in'])

    token = OAuth2Token(params, old_scope=scope)

    if state and params.get('state') != state:
        raise ValueError("Mismatching or missing state in response.")

    validate_token_parameters(token)
    return token

def validate_token_parameters(params):
    if 'error' in params:
        raise_from_error(params.get('error'), params)

    if 'access_token' not in params:
        raise MissingTokenError(description='Missing access token parameter.')

    if 'token_type' not in params and os.environ.get('OAUTHLIB_STRICT_TOKEN_TYPE'):
        raise MissingTokenTypeError()

    if params.scope_changed:
        if os.environ.get('OAUTHLIB_RELAX_TOKEN_SCOPE'):
            new_scope = params.scope
            old_scope = params.old_scope
            message = 'Scope has changed from "{old}" to "{new}".'.format(
                old=list_to_scope(old_scope),
                new=list_to_scope(new_scope),
            )
            scope_changed.send(message=message, old=old_scope, new=new_scope)
        else:
            raise Warning("Scope has changed from \"%s\" to \"%s\"." % (
                list_to_scope(params.old_scope), list_to_scope(params.scope)))
